import gurobipy
from gurobipy import GRB

def solve_problem():
    table = CSVQA_DATA['tables'][0]
    records = table['records']
    I = []
    c = {}
    npv = {}
    for rec in records:
        values = rec['values']
        proj_id = values['Project ID']
        I.append(proj_id)
        try:
            c_val = float(values['Capital (k$)'])
        except (KeyError, ValueError):
            raise ValueError(f'Missing or invalid Capital for project {proj_id}')
        try:
            npv_val = float(values['NPV (k$)'])
        except (KeyError, ValueError):
            raise ValueError(f'Missing or invalid NPV for project {proj_id}')
        c[proj_id] = c_val
        npv[proj_id] = npv_val
    required_ids = ['1', '4', '5', '6', '7', '10']
    for pid in required_ids:
        if pid not in I:
            raise ValueError(f'Required project ID {pid} not found in data')
    m = gurobipy.Model()
    m.setParam('MIPGap', 1e-06)
    x = m.addVars(I, vtype=GRB.BINARY, name='')
    m.setObjective(gurobipy.quicksum((npv[i] * x[i] for i in I)), GRB.MAXIMIZE)
    m.addConstr(gurobipy.quicksum((c[i] * x[i] for i in I)) <= 1000, name='budget')
    m.addConstr(x['4'] + x['7'] <= 1, name='mut_excl_4_7')
    m.addConstr(x['6'] <= x['1'], name='prereq_6_1')
    m.addConstr(x['10'] <= x['5'], name='contingent_10_5')
    m.optimize()
    return m
m = solve_problem()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
